BEGIN READ ONLY;SET LOCAL statement_timeout='10s'; SELECT jsonb_build_object('sync_rows',(SELECT count(*) FROM public.sync_records),'non_object_payloads',(SELECT count(*) FROM public.sync_records WHERE jsonb_typeof(payload) IS DISTINCT FROM 'object'),'business_shop_mismatches',(SELECT count(*) FROM public.sync_records sr JOIN public.shops sh ON sh.id=sr.shop_id WHERE sr.business_id<>sh.business_id),'unknown_sync_tables',(SELECT count(*) FROM public.sync_records WHERE table_name NOT IN ('events','products','accounts','budget_plans','collections_targets','deliveries','attendance_records','delivery_status_history','daily_close_actions','physical_cash_counts','settings','store_profile'))) AS integrity;ROLLBACK;
